    void DrawEdges(){foreach(var line in lines)graph.Children.Remove(line);lines.Clear();routeCrossings=0;var occupied=boxes.Keys.Select(id=>new Rect(positions[id].X-3,positions[id].Y-3,236,84)).ToList();int edgeIndex=0;foreach(var (from,to,kind,evidence) in connections){if(!boxes.ContainsKey(from)||!boxes.ContainsKey(to))continue;Point a=positions[from],b=positions[to];Point p,q;if(Math.Abs(a.X-b.X)>Math.Abs(a.Y-b.Y)){bool right=b.X>a.X;p=new Point(a.X+(right?230:0),a.Y+39);q=new Point(b.X+(right?0:230),b.Y+39);}else{bool down=b.Y>a.Y;p=new Point(a.X+115,a.Y+(down?78:0));q=new Point(b.X+115,b.Y+(down?0:78));}
