    static List<Point> Route(Point p,Point q,Rect from,Rect to,Rect[] boxes){
        Point Dock(Point point,Rect box)=>point.X==box.Left?new Point(point.X-14,point.Y):point.X==box.Right?new Point(point.X+14,point.Y):point.Y==box.Top?new Point(point.X,point.Y-14):new Point(point.X,point.Y+14);
        Point start=Dock(p,from),end=Dock(q,to);var obstacles=boxes.Select(r=>{r.Inflate(7,7);return r;}).ToArray();
        if(!obstacles.Any(r=>SegmentHits(start,end,r)))return[p,start,end,q];
        var xs=obstacles.SelectMany(r=>new[]{r.Left-5,r.Right+5}).Append(start.X).Append(end.X).Distinct().Order().ToArray();var ys=obstacles.SelectMany(r=>new[]{r.Top-5,r.Bottom+5}).Append(start.Y).Append(end.Y).Distinct().Order().ToArray();int width=xs.Length;
        int Key(Point point)=>Array.IndexOf(ys,point.Y)*width+Array.IndexOf(xs,point.X);Point Location(int key)=>new(xs[key%width],ys[key/width]);int first=Key(start),last=Key(end);
        var cost=new Dictionary<int,double>{{first,0}};var previous=new Dictionary<int,int>();var pending=new PriorityQueue<int,double>();pending.Enqueue(first,0);
        while(pending.TryDequeue(out int current,out _)){if(current==last)break;int x=current%width,y=current/width;foreach(var (nx,ny) in new[]{(x-1,y),(x+1,y),(x,y-1),(x,y+1)}){if(nx<0||ny<0||nx>=width||ny>=ys.Length)continue;int next=ny*width+nx;Point a=Location(current),b=Location(next);if(obstacles.Any(r=>SegmentHits(a,b,r)))continue;double distance=cost[current]+(b-a).Length+0.01;if(cost.TryGetValue(next,out var existing)&&existing<=distance)continue;cost[next]=distance;previous[next]=current;pending.Enqueue(next,distance+Math.Abs(end.X-b.X)+Math.Abs(end.Y-b.Y));}}
        if(!cost.ContainsKey(last))return[p,start,end,q];var path=new List<Point>{end};for(int current=last;current!=first;){current=previous[current];path.Add(Location(current));}path.Reverse();var result=new List<Point>{p};foreach(var point in path){if(result.Count>=2){var a=result[^1]-result[^2];var b=point-result[^1];if(Math.Abs(Vector.CrossProduct(a,b))<.001)result.RemoveAt(result.Count-1);}result.Add(point);}result.Add(q);return result;
    }
    static bool SegmentHits(Point a,Point b,Rect r){double low=0,high=1;Vector d=b-a;bool Clip(double p,double q){if(Math.Abs(p)<.000001)return q>0;double t=q/p;if(p<0)low=Math.Max(low,t);else high=Math.Min(high,t);return low<high;}return Clip(-d.X,a.X-r.Left)&&Clip(d.X,r.Right-a.X)&&Clip(-d.Y,a.Y-r.Top)&&Clip(d.Y,r.Bottom-a.Y);}
