    async Task RenderDetails(){if(state?["snapshot"]==null)return;if(activeAction!=""){await RenderAction();return;}if(selected==""||Node(selected)==null){selection.Text="Project memory";detail.Text="Select a module to see its source and relationships.\n\nDouble-click a file to open its declarations. Drag nodes to arrange the map.\n\nCLI activity is recorded separately from filesystem observations.\n\n"+Str(state["snapshot"],"scope");return;}
