        string relative="native-probe-"+Guid.NewGuid().ToString("N")+".js",folder=Str(state?["project"],"root"),file=System.IO.Path.Combine(folder,relative),actionId=Guid.NewGuid().ToString("N"),sessionId="native-acceptance";
        bool automatic=state?["autoExplain"]?.GetValue<bool>()??true;await Post("/settings",new{autoExplain=false});
        try{
            await Tool("lens.action_report",new{projectId=pid,sessionId,eventId="start-"+actionId,actionId,phase="started",baseRevision=rev,files=new[]{relative},intent="Create a module to verify the live MCP-to-panel path.",rationale="Native acceptance probe; remove it after verification."});
            await File.WriteAllTextAsync(file,"export function nativeProbe() { return 'live MCP'; }\n");
            JsonNode? observed=null;for(int i=0;i<60;i++){await Task.Delay(200);observed=await Get("/state");if(Arr(observed?["snapshot"],"nodes").Any(n=>Str(n,"path")==relative))break;}
            var probe=Arr(observed?["snapshot"],"nodes").FirstOrDefault(n=>Str(n,"path")==relative&&Str(n,"parentId")=="")??throw new Exception("Native probe did not reach the file watcher.");passed.Add("Real file write appears in live graph");
            await Tool("lens.action_report",new{projectId=pid,sessionId,eventId="done-"+actionId,actionId,phase="completed",baseRevision=rev,files=new[]{relative},outcome="Probe module observed by the source watcher."});
            var recorded=await Tool("lens.action_get",new{projectId=pid,actionId});if(Str(recorded["action"],"attribution")!="reported_and_correlated")throw new Exception("Probe action was not correlated.");passed.Add("Action report correlated with observed source");
