        }finally{if(File.Exists(file))File.Delete(file);await Post("/settings",new{autoExplain=automatic});}
        await child.StandardInput.DisposeAsync();if(!child.WaitForExit(3000))child.Kill();
        var cliStart=new ProcessStartInfo(node){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=folder,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var a in new[]{System.IO.Path.Combine(directory,"cli.cjs"),"--connection",connectionPath,"--intent","Run the queue regression tests","--files","queue.test.js","--",node,"queue.test.js"})cliStart.ArgumentList.Add(a);
        using var cli=Process.Start(cliStart)??throw new Exception("CLI adapter did not start.");var stdout=cli.StandardOutput.ReadToEndAsync();var stderr=cli.StandardError.ReadToEndAsync();await cli.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(35));string output=await stdout+await stderr;File.WriteAllText(System.IO.Path.Combine(statePath,"cli-adapter-tests.log"),output);if(cli.ExitCode!=0)throw new Exception("CLI adapter test failed; see cli-adapter-tests.log.");passed.Add("Real CLI command adapter and direct node:test source execution exit 0");
        await Task.Delay(700);await Poll();File.WriteAllText(System.IO.Path.Combine(statePath,"mcp-native-result.json"),JsonSerializer.Serialize(new{ok=true,passed,notifications,scope="Actual subprocess stdio MCP bridge, source watcher, action reports, source/context retrieval, subscriptions and CLI command adapter."},new JsonSerializerOptions{WriteIndented=true}));
    }
    void Capture(string file){UpdateLayout();if(routeCrossings>0)throw new Exception("A relationship crosses an unrelated module card.");var rectangles=boxes.Keys.Select(id=>new Rect(positions[id].X,positions[id].Y,230,78)).ToArray();for(int i=0;i<rectangles.Length;i++)for(int j=i+1;j<rectangles.Length;j++)if(rectangles[i].IntersectsWith(rectangles[j]))throw new Exception("Visible module cards overlap.");var bitmap=new RenderTargetBitmap((int)Math.Ceiling(ActualWidth),(int)Math.Ceiling(ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(this);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using var output=File.Create(file);encoder.Save(output);}
    void CaptureDesktop(string file){var origin=PointToScreen(new Point(0,0));var dpi=VisualTreeHelper.GetDpi(this);using var bitmap=new System.Drawing.Bitmap((int)Math.Ceiling(ActualWidth*dpi.DpiScaleX),(int)Math.Ceiling(ActualHeight*dpi.DpiScaleY));using var graphics=System.Drawing.Graphics.FromImage(bitmap);graphics.CopyFromScreen((int)origin.X,(int)origin.Y,0,0,bitmap.Size,System.Drawing.CopyPixelOperation.SourceCopy);bitmap.Save(file,System.Drawing.Imaging.ImageFormat.Png);}
